// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX, Log} from "../src/MONEY_BOX.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MONEY_BOX c;

    function setUp() public { c = new MONEY_BOX(); }

    function testFuzz_property(uint256 amount, address actor, uint256 lockTime) public {
        vm.assume(amount <= VALUE_CAP);
        Log log = new Log();
        c.SetLogFile(address(log));

        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        try c.Put{value: amount}(lockTime) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok);
    }
}
